        raise ValueError("Invalid JSON: must end with '}' or ']'")
    if json_str.count('{') != json_str.count('}'):
        raise ValueError("Invalid JSON: unbalanced '{' and '}'")
    if json_str.count('[') != json_str.count(']'):
        raise ValueError("Invalid JSON: unbalanced '[' and ']'")
    def parse_object(json_str):
        if not json_str:
            raise ValueError("Invalid JSON: empty object")
        if json_str[0] != '{':
            raise ValueError("Invalid JSON: object must start with '{'")
        if json_str[-1] != '}':
            raise ValueError("Invalid JSON: object must end with '}'")
        json_str = json_str[1:-1]
        members = json_str.split(',')
        obj = {}
        for member in members:
            member = member.strip()
            if not member:
                continue
            key, value = member.split(':')
            key = key.strip().strip('"')
            value = value.strip().strip('"')
            obj[key] = parse_value(value)
        return obj
    def parse_array(json_str):
        if not json_str:
            raise ValueError("Invalid JSON: empty array")
        if json_str[0] != '[':
            raise ValueError("Invalid JSON: array must start with '['")
        if json_str[-1] != ']':
            raise ValueError("Invalid JSON: array must end with ']'")
        json_str = json_str[1:-1]
        elements = json_str.split(',')
        arr = []
        for element in elements:
            element = element.strip()
            if not element:
                continue
            arr.append(parse_value(element))
        return arr
    def parse_value(json_str):
        if json_str.startswith('"'):
            return parse_string(json_str)
        elif json_str.isdigit():
            return int(json_str)
        elif json_str.lower() == 'true':
            return True
        elif json_str.lower() == 'false':
            return False
        elif json_str.lower() == 'null':
            return None
        elif json_str.startswith('{'):
            return parse_object(json_str)
        elif json_str.startswith('['):
            return parse_array(json_str)
        else:
            raise ValueError("Invalid JSON: unexpected value")
    def parse_string(json_str):
